22	const PROCESSING_FEE = 5;
23	const FIRST_INSURANCE_SURCHARGE = 0.1;
24	const CURSE_SURCHARGE = 0.5;
25	const HIGH_ENCHANTMENT_SURCHARGE = 0.3;
26	const HIGH_ENCHANTMENT_THRESHOLD = 5;
27	
28	/** Premiums are rounded up (in the MHPCO's favour), ignoring float noise. */
29	const roundUp = (amount: number): number => Math.ceil(Number(amount.toFixed(6)));
30	
31	const BASE_PREMIUMS: Record<string, number> = {
32	  sword: 100,
33	  amulet: 60,
34	  staff: 80,
35	  potion: 40,
36	  rune: 25,
37	  moonstone: 25,
38	};
39	
40	const COMPONENT_TYPES = ["rune", "moonstone"];
41	const BLOCK_SIZE = 3;
42	const BLOCK_BASE_PREMIUM = 60;
43	
44	const isComponent = (type: string): boolean => COMPONENT_TYPES.includes(type);
45	
46	const countByType = (items: Item[]): Map<string, number> => {
47	  const counts = new Map<string, number>();
48	
49	  for (const item of items) {
50	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
51	  }
52	
53	  return counts;
54	};
55	
56	/** Exactly BLOCK_SIZE alike components form a building block. */
57	const formsBuildingBlock = (type: string, count: number): boolean =>
58	  isComponent(type) && count === BLOCK_SIZE;
59	
60	const itemBasePremium = (type: string): number => BASE_PREMIUMS[type];
61	
62	/** Alike items are priced together so a building block can be recognised. */
63	const groupBasePremium = (type: string, count: number): number =>
64	  formsBuildingBlock(type, count)
65	    ? BLOCK_BASE_PREMIUM
66	    : count * itemBasePremium(type);
67	
68	/** The policy base premium is the sum of the base premiums of its items. */
69	const policyBasePremium = (items: Item[]): number =>
70	  [...countByType(items)].reduce(
71	    (total, [type, count]) => total + groupBasePremium(type, count),
72	    0,
73	  );
74	
75	/** The item-specific surcharge rates an item attracts, as fractions of its base premium. */
76	const itemSurchargeRate = (item: Item): number =>
77	  (item.cursed ? CURSE_SURCHARGE : 0) +
78	  ((item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD
79	    ? HIGH_ENCHANTMENT_SURCHARGE
80	    : 0);
81	
82	/**
83	 * Item-specific modifiers apply to the base premium of the affected item,
84	 * not to the policy total.
85	 */
86	const itemSurcharges = (items: Item[]): number =>
87	  items.reduce(
88	    (total, item) =>
89	      total + itemBasePremium(item.type) * itemSurchargeRate(item),
90	    0,
91	  );
92	
93	/**
94	 * Modifiers are expressed as amounts added to (or subtracted from) the base
95	 * premium they apply to, so several modifiers stack additively rather than
96	 * compounding.
97	 */
98	const quotePremium = (step: QuoteStep): number => {
99	  const basePremium = policyBasePremium(step.items);
100	  const firstInsuranceSurcharge = basePremium * FIRST_INSURANCE_SURCHARGE;
101	
102	  return roundUp(
103	    basePremium +
104	      itemSurcharges(step.items) +
105	      firstInsuranceSurcharge +
106	      PROCESSING_FEE,
107	  );
108	};
109	
110	export const runScenario = (scenario: Scenario): ScenarioResults => ({
111	  results: scenario.steps.map((step) => ({ premium: quotePremium(step) })),
112	});
